-- Context budgets, exact source receipts, Agent assets and durable source synchronization.

-- Generated by tools/v501_generate_context_assets.py; source facts remain relational and currently authorized.

-- Synchronization proposes candidates only; independent review and explicit publication are unchanged.

CREATE TABLE IF NOT EXISTS CX_CONTEXT_BUDGETS (ASSEMBLY_ID VARCHAR(128) PRIMARY KEY REFERENCES CX_CONTEXT_ASSEMBLIES(ASSEMBLY_ID), COUNT_METHOD VARCHAR(128) NOT NULL, MODEL_NAME VARCHAR(200), CONTEXT_WINDOW INTEGER NOT NULL CHECK(CONTEXT_WINDOW>0), OUTPUT_RESERVE INTEGER NOT NULL CHECK(OUTPUT_RESERVE>=0), SYSTEM_TOKENS INTEGER NOT NULL CHECK(SYSTEM_TOKENS>=0), TOOL_TOKENS INTEGER NOT NULL CHECK(TOOL_TOKENS>=0), SOURCE_BUDGET INTEGER NOT NULL CHECK(SOURCE_BUDGET>=0), BYTE_BUDGET INTEGER NOT NULL CHECK(BYTE_BUDGET>0), QUERY_DIGEST VARCHAR(64) NOT NULL, CHECK(SOURCE_BUDGET+SYSTEM_TOKENS+TOOL_TOKENS+OUTPUT_RESERVE<=CONTEXT_WINDOW));

CREATE TABLE IF NOT EXISTS CX_CONTEXT_REPRESENTATIONS (ASSEMBLY_ID VARCHAR(128) NOT NULL REFERENCES CX_CONTEXT_ASSEMBLIES(ASSEMBLY_ID), SOURCE_NO INTEGER NOT NULL CHECK(SOURCE_NO>0), ITEM_NO INTEGER, FAMILY VARCHAR(24) NOT NULL, ENTITY_ID VARCHAR(128) NOT NULL, REVISION_ID VARCHAR(128) NOT NULL, CONTENT_DIGEST VARCHAR(64) NOT NULL, RENDERED_DIGEST VARCHAR(64), REPRESENTATION VARCHAR(16) NOT NULL CHECK(REPRESENTATION IN ('COMPLETE','PARTIAL','OMITTED')), SELECTION_REASON VARCHAR(64) NOT NULL, RANK_SCORE INTEGER NOT NULL, TOKEN_COUNT INTEGER NOT NULL CHECK(TOKEN_COUNT>=0), BYTE_COUNT INTEGER NOT NULL CHECK(BYTE_COUNT>=0), DELIVERY_STATUS VARCHAR(16) NOT NULL CHECK(DELIVERY_STATUS IN ('PREPARED','CONFIRMED','UNOBSERVED','OMITTED')), PRIMARY KEY(ASSEMBLY_ID,SOURCE_NO), FOREIGN KEY(ASSEMBLY_ID,ITEM_NO) REFERENCES CX_CONTEXT_ASSEMBLY_ITEMS(ASSEMBLY_ID,ITEM_NO));

CREATE TABLE IF NOT EXISTS CX_AGENT_ASSET_BINDINGS (BINDING_ID VARCHAR(128) PRIMARY KEY, AGENT_ID VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), SECURITY_DOMAIN_ID VARCHAR(128) NOT NULL REFERENCES CX_SECURITY_DOMAINS(SECURITY_DOMAIN_ID), OWNER_PRINCIPAL_ID VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), CURRENT_REVISION INTEGER NOT NULL CHECK(CURRENT_REVISION>0), ROW_VERSION INTEGER NOT NULL CHECK(ROW_VERSION>0), STATUS VARCHAR(16) NOT NULL CHECK(STATUS IN ('ACTIVE','PAUSED','REVOKED')), CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);

CREATE TABLE IF NOT EXISTS CX_AGENT_ASSET_REVISIONS (BINDING_ID VARCHAR(128) NOT NULL REFERENCES CX_AGENT_ASSET_BINDINGS(BINDING_ID), REVISION_NO INTEGER NOT NULL CHECK(REVISION_NO>0), FAMILY VARCHAR(24) NOT NULL CHECK(FAMILY IN ('MEMORY','KNOWLEDGE','SKILL','GRAPH','SOURCE')), ENTITY_ID VARCHAR(128) NOT NULL, REVISION_ID VARCHAR(128) NOT NULL, CONTENT_DIGEST VARCHAR(64) NOT NULL, PURPOSE VARCHAR(1000) NOT NULL, PRIORITY INTEGER NOT NULL CHECK(PRIORITY>=0 AND PRIORITY<=100), RESOLUTION_POLICY VARCHAR(16) NOT NULL CHECK(RESOLUTION_POLICY IN ('PINNED','CURRENT')), VALID_UNTIL TIMESTAMP, CREATED_BY VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), REASON VARCHAR(1000) NOT NULL, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, PRIMARY KEY(BINDING_ID,REVISION_NO));

CREATE TABLE IF NOT EXISTS CX_AGENT_ASSET_REQUESTS (ACTOR_ID VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), IDEMPOTENCY_KEY VARCHAR(128) NOT NULL, REQUEST_DIGEST VARCHAR(64) NOT NULL, BINDING_ID VARCHAR(128) NOT NULL REFERENCES CX_AGENT_ASSET_BINDINGS(BINDING_ID), RESOURCE_VERSION INTEGER NOT NULL CHECK(RESOURCE_VERSION>0), CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, PRIMARY KEY(ACTOR_ID,IDEMPOTENCY_KEY));

CREATE TABLE IF NOT EXISTS CX_CONTEXT_ASSET_USES (ASSEMBLY_ID VARCHAR(128) NOT NULL REFERENCES CX_CONTEXT_ASSEMBLIES(ASSEMBLY_ID), BINDING_ID VARCHAR(128) NOT NULL REFERENCES CX_AGENT_ASSET_BINDINGS(BINDING_ID), BINDING_VERSION INTEGER NOT NULL CHECK(BINDING_VERSION>0), FAMILY VARCHAR(24) NOT NULL, ENTITY_ID VARCHAR(128) NOT NULL, REVISION_ID VARCHAR(128) NOT NULL, CONTENT_DIGEST VARCHAR(64) NOT NULL, PRIMARY KEY(ASSEMBLY_ID,BINDING_ID));

CREATE TABLE IF NOT EXISTS CX_AGENT_SOURCES (SOURCE_ID VARCHAR(128) PRIMARY KEY, AGENT_ID VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), OWNER_PRINCIPAL_ID VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), SECURITY_DOMAIN_ID VARCHAR(128) NOT NULL REFERENCES CX_SECURITY_DOMAINS(SECURITY_DOMAIN_ID), SOURCE_KIND VARCHAR(16) NOT NULL CHECK(SOURCE_KIND IN ('DOCUMENT','GITHUB')), ENDPOINT VARCHAR(2000) NOT NULL, PINNED_COMMIT VARCHAR(40), CREDENTIAL_REF VARCHAR(100), CONTENT_POLICY_DIGEST VARCHAR(64) NOT NULL, CONFIG_DIGEST VARCHAR(64) NOT NULL, ROW_VERSION INTEGER NOT NULL CHECK(ROW_VERSION>0), MAX_BYTES INTEGER NOT NULL CHECK(MAX_BYTES>=128 AND MAX_BYTES<=262144), MAX_ATTEMPTS INTEGER NOT NULL CHECK(MAX_ATTEMPTS>=1 AND MAX_ATTEMPTS<=5), STATUS VARCHAR(16) NOT NULL CHECK(STATUS IN ('ACTIVE','PAUSED','REVOKED','RETIRED')), CURRENT_REVISION_ID VARCHAR(128), CHECKPOINT_DIGEST VARCHAR(64), CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);

CREATE TABLE IF NOT EXISTS CX_AGENT_SOURCE_PATHS (SOURCE_ID VARCHAR(128) NOT NULL REFERENCES CX_AGENT_SOURCES(SOURCE_ID), PATH_NO INTEGER NOT NULL CHECK(PATH_NO>0), SOURCE_PATH VARCHAR(500) NOT NULL, PRIMARY KEY(SOURCE_ID,PATH_NO), UNIQUE(SOURCE_ID,SOURCE_PATH));

CREATE TABLE IF NOT EXISTS CX_AGENT_SOURCE_TYPES (SOURCE_ID VARCHAR(128) NOT NULL REFERENCES CX_AGENT_SOURCES(SOURCE_ID), CONTENT_TYPE VARCHAR(100) NOT NULL, PRIMARY KEY(SOURCE_ID,CONTENT_TYPE));

CREATE TABLE IF NOT EXISTS CX_AGENT_SOURCE_REVISIONS (REVISION_ID VARCHAR(128) PRIMARY KEY, SOURCE_ID VARCHAR(128) NOT NULL REFERENCES CX_AGENT_SOURCES(SOURCE_ID), SOURCE_VERSION VARCHAR(256) NOT NULL, SOURCE_PATH VARCHAR(500) NOT NULL, TITLE VARCHAR(500) NOT NULL, CONTENT_DIGEST VARCHAR(64) NOT NULL, CONTENT_CIPHER TEXT NOT NULL, OBSERVED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, EFFECTIVE_AT TIMESTAMP, LIFECYCLE_STATE VARCHAR(16) NOT NULL CHECK(LIFECYCLE_STATE IN ('AVAILABLE','UNAVAILABLE','RETIRED')), UNIQUE(SOURCE_ID,SOURCE_VERSION,SOURCE_PATH,CONTENT_DIGEST));

CREATE TABLE IF NOT EXISTS CX_AGENT_SYNC_JOBS (JOB_ID VARCHAR(128) PRIMARY KEY, SOURCE_ID VARCHAR(128) NOT NULL REFERENCES CX_AGENT_SOURCES(SOURCE_ID), CONTINUITY_ID VARCHAR(128) NOT NULL UNIQUE REFERENCES CX_TASK_CONTINUITY_LINKS(CONTINUITY_ID), REQUESTED_BY VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), CONFIG_DIGEST VARCHAR(64) NOT NULL, REQUEST_DIGEST VARCHAR(64) NOT NULL, STATUS VARCHAR(16) NOT NULL CHECK(STATUS IN ('PENDING','RUNNING','SUCCEEDED','FAILED','BLOCKED')), ATTEMPT_COUNT INTEGER NOT NULL CHECK(ATTEMPT_COUNT>=0), ERROR_CODE VARCHAR(64), CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);

CREATE TABLE IF NOT EXISTS CX_AGENT_SYNC_IMPORTS (JOB_ID VARCHAR(128) NOT NULL REFERENCES CX_AGENT_SYNC_JOBS(JOB_ID), REVISION_ID VARCHAR(128) NOT NULL REFERENCES CX_AGENT_SOURCE_REVISIONS(REVISION_ID), CANDIDATE_ID VARCHAR(128) NOT NULL REFERENCES CX_ARTIFACT_CANDIDATES(CANDIDATE_ID), CANDIDATE_REVISION INTEGER NOT NULL CHECK(CANDIDATE_REVISION>0), PRIMARY KEY(JOB_ID,REVISION_ID));

CREATE TABLE IF NOT EXISTS CX_AGENT_SOURCE_REQUESTS (ACTOR_ID VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), IDEMPOTENCY_KEY VARCHAR(128) NOT NULL, REQUEST_DIGEST VARCHAR(64) NOT NULL, SOURCE_ID VARCHAR(128) NOT NULL REFERENCES CX_AGENT_SOURCES(SOURCE_ID), JOB_ID VARCHAR(128) REFERENCES CX_AGENT_SYNC_JOBS(JOB_ID), RESOURCE_VERSION INTEGER NOT NULL CHECK(RESOURCE_VERSION>0), CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, PRIMARY KEY(ACTOR_ID,IDEMPOTENCY_KEY));

CREATE OR REPLACE FUNCTION cx104_reject_context_asset_mutation() RETURNS trigger LANGUAGE plpgsql AS $cx104$ BEGIN RAISE EXCEPTION 'Context and asset history is immutable' USING ERRCODE='23000'; END $cx104$;

REVOKE ALL ON FUNCTION cx104_reject_context_asset_mutation() FROM PUBLIC;

CREATE OR REPLACE TRIGGER CX104_501333FF2BC22F2B BEFORE DELETE OR UPDATE OF ASSEMBLY_ID,COUNT_METHOD,MODEL_NAME,CONTEXT_WINDOW,OUTPUT_RESERVE,SYSTEM_TOKENS,TOOL_TOKENS,SOURCE_BUDGET,BYTE_BUDGET,QUERY_DIGEST ON CX_CONTEXT_BUDGETS FOR EACH STATEMENT EXECUTE FUNCTION cx104_reject_context_asset_mutation();

REVOKE ALL ON CX_CONTEXT_BUDGETS FROM PUBLIC, ai_agent_runtime;

CREATE OR REPLACE TRIGGER CX104_A3EE623B46D2CE9F BEFORE DELETE OR UPDATE OF ASSEMBLY_ID,SOURCE_NO,ITEM_NO,FAMILY,ENTITY_ID,REVISION_ID,CONTENT_DIGEST,RENDERED_DIGEST,REPRESENTATION,SELECTION_REASON,RANK_SCORE,TOKEN_COUNT,BYTE_COUNT ON CX_CONTEXT_REPRESENTATIONS FOR EACH STATEMENT EXECUTE FUNCTION cx104_reject_context_asset_mutation();

REVOKE ALL ON CX_CONTEXT_REPRESENTATIONS FROM PUBLIC, ai_agent_runtime;

CREATE OR REPLACE TRIGGER CX104_E9E202F558E1923B BEFORE DELETE OR UPDATE OF BINDING_ID,AGENT_ID,SECURITY_DOMAIN_ID,OWNER_PRINCIPAL_ID,CREATED_AT ON CX_AGENT_ASSET_BINDINGS FOR EACH STATEMENT EXECUTE FUNCTION cx104_reject_context_asset_mutation();

REVOKE ALL ON CX_AGENT_ASSET_BINDINGS FROM PUBLIC, ai_agent_runtime;

CREATE OR REPLACE TRIGGER CX104_C7309AB9E8DA3A43 BEFORE DELETE OR UPDATE OF BINDING_ID,REVISION_NO,FAMILY,ENTITY_ID,REVISION_ID,CONTENT_DIGEST,PURPOSE,PRIORITY,RESOLUTION_POLICY,VALID_UNTIL,CREATED_BY,REASON,CREATED_AT ON CX_AGENT_ASSET_REVISIONS FOR EACH STATEMENT EXECUTE FUNCTION cx104_reject_context_asset_mutation();

REVOKE ALL ON CX_AGENT_ASSET_REVISIONS FROM PUBLIC, ai_agent_runtime;

CREATE OR REPLACE TRIGGER CX104_95F086E0530BAC17 BEFORE DELETE OR UPDATE OF ACTOR_ID,IDEMPOTENCY_KEY,REQUEST_DIGEST,BINDING_ID,RESOURCE_VERSION,CREATED_AT ON CX_AGENT_ASSET_REQUESTS FOR EACH STATEMENT EXECUTE FUNCTION cx104_reject_context_asset_mutation();

REVOKE ALL ON CX_AGENT_ASSET_REQUESTS FROM PUBLIC, ai_agent_runtime;

CREATE OR REPLACE TRIGGER CX104_8D35CBD2645A0F9F BEFORE DELETE OR UPDATE OF ASSEMBLY_ID,BINDING_ID,BINDING_VERSION,FAMILY,ENTITY_ID,REVISION_ID,CONTENT_DIGEST ON CX_CONTEXT_ASSET_USES FOR EACH STATEMENT EXECUTE FUNCTION cx104_reject_context_asset_mutation();

REVOKE ALL ON CX_CONTEXT_ASSET_USES FROM PUBLIC, ai_agent_runtime;

CREATE OR REPLACE TRIGGER CX104_90B8FBFE4D697E6F BEFORE DELETE OR UPDATE OF SOURCE_ID,AGENT_ID,OWNER_PRINCIPAL_ID,SECURITY_DOMAIN_ID,SOURCE_KIND,ENDPOINT,PINNED_COMMIT,CREDENTIAL_REF,CONTENT_POLICY_DIGEST,CONFIG_DIGEST,MAX_BYTES,MAX_ATTEMPTS,CREATED_AT ON CX_AGENT_SOURCES FOR EACH STATEMENT EXECUTE FUNCTION cx104_reject_context_asset_mutation();

REVOKE ALL ON CX_AGENT_SOURCES FROM PUBLIC, ai_agent_runtime;

CREATE OR REPLACE TRIGGER CX104_44A116C5CC9FA10B BEFORE DELETE OR UPDATE OF SOURCE_ID,PATH_NO,SOURCE_PATH ON CX_AGENT_SOURCE_PATHS FOR EACH STATEMENT EXECUTE FUNCTION cx104_reject_context_asset_mutation();

REVOKE ALL ON CX_AGENT_SOURCE_PATHS FROM PUBLIC, ai_agent_runtime;

CREATE OR REPLACE TRIGGER CX104_AB9D5C1F538C3215 BEFORE DELETE OR UPDATE OF SOURCE_ID,CONTENT_TYPE ON CX_AGENT_SOURCE_TYPES FOR EACH STATEMENT EXECUTE FUNCTION cx104_reject_context_asset_mutation();

REVOKE ALL ON CX_AGENT_SOURCE_TYPES FROM PUBLIC, ai_agent_runtime;

CREATE OR REPLACE TRIGGER CX104_16D9334355AF2AC6 BEFORE DELETE OR UPDATE OF REVISION_ID,SOURCE_ID,SOURCE_VERSION,SOURCE_PATH,TITLE,CONTENT_DIGEST,CONTENT_CIPHER,OBSERVED_AT,EFFECTIVE_AT ON CX_AGENT_SOURCE_REVISIONS FOR EACH STATEMENT EXECUTE FUNCTION cx104_reject_context_asset_mutation();

REVOKE ALL ON CX_AGENT_SOURCE_REVISIONS FROM PUBLIC, ai_agent_runtime;

CREATE OR REPLACE TRIGGER CX104_A96DEB2672B1DAF8 BEFORE DELETE OR UPDATE OF JOB_ID,SOURCE_ID,CONTINUITY_ID,REQUESTED_BY,CONFIG_DIGEST,REQUEST_DIGEST,CREATED_AT ON CX_AGENT_SYNC_JOBS FOR EACH STATEMENT EXECUTE FUNCTION cx104_reject_context_asset_mutation();

REVOKE ALL ON CX_AGENT_SYNC_JOBS FROM PUBLIC, ai_agent_runtime;

CREATE OR REPLACE TRIGGER CX104_0CB4AAEBADAC93E0 BEFORE DELETE OR UPDATE OF JOB_ID,REVISION_ID,CANDIDATE_ID,CANDIDATE_REVISION ON CX_AGENT_SYNC_IMPORTS FOR EACH STATEMENT EXECUTE FUNCTION cx104_reject_context_asset_mutation();

REVOKE ALL ON CX_AGENT_SYNC_IMPORTS FROM PUBLIC, ai_agent_runtime;

CREATE OR REPLACE TRIGGER CX104_353BFEC37B4AC177 BEFORE DELETE OR UPDATE OF ACTOR_ID,IDEMPOTENCY_KEY,REQUEST_DIGEST,SOURCE_ID,JOB_ID,RESOURCE_VERSION,CREATED_AT ON CX_AGENT_SOURCE_REQUESTS FOR EACH STATEMENT EXECUTE FUNCTION cx104_reject_context_asset_mutation();

REVOKE ALL ON CX_AGENT_SOURCE_REQUESTS FROM PUBLIC, ai_agent_runtime;

CREATE INDEX IF NOT EXISTS CX104_ASSET_AGENT ON CX_AGENT_ASSET_BINDINGS(AGENT_ID,SECURITY_DOMAIN_ID,STATUS);

CREATE INDEX IF NOT EXISTS CX104_SOURCE_AGENT ON CX_AGENT_SOURCES(AGENT_ID,SECURITY_DOMAIN_ID,STATUS);

CREATE INDEX IF NOT EXISTS CX104_SYNC_SOURCE ON CX_AGENT_SYNC_JOBS(SOURCE_ID,STATUS);

CREATE INDEX IF NOT EXISTS CX104_SOURCE_REVS ON CX_AGENT_SOURCE_REVISIONS(SOURCE_ID,LIFECYCLE_STATE);
